/* ================= About (native page, composed from the design system) ================= */
.pg-about main{overflow:clip}
/* hero: aurora sky like the homepage, story left, the founders in the one liquid-glass frame */
.ab-hero{position:relative;padding:calc(var(--nav-h) + clamp(56px,8vw,110px)) 0 clamp(64px,8vw,110px);isolation:isolate}
.ab-sky{position:absolute;inset:0;z-index:-1;background:
  radial-gradient(60% 55% at 12% 8%,rgba(62,220,242,.16),transparent 62%),
  radial-gradient(55% 60% at 88% 0%,rgba(123,58,245,.22),transparent 64%),
  radial-gradient(40% 40% at 60% 100%,rgba(20,99,255,.12),transparent 70%)}
.ab-sky::after{content:"";position:absolute;inset:auto 0 0;height:180px;background:linear-gradient(180deg,transparent,var(--bg))}
.ab-hero-in{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(0,.85fr);gap:clamp(40px,6vw,88px);align-items:center}
.ab-hero h1{margin:0 0 22px;font-size:clamp(2.2rem,4.1vw,3.5rem);line-height:1.06;letter-spacing:-.032em;font-weight:800;text-wrap:balance;max-width:20ch}
.ab-hero h1 span{background:linear-gradient(100deg,#3EDCF2,#4E8DFF 42%,#9B6BFF);-webkit-background-clip:text;background-clip:text;color:transparent}
.ab-lede{color:var(--ink-2);font-size:clamp(1.05rem,1.3vw,1.18rem);line-height:1.7;max-width:56ch;margin:0 0 30px}
.ab-photo{margin:0;justify-self:end;width:min(100%,440px)}
.ab-photo img{display:block;width:100%;height:auto;aspect-ratio:4/5;object-fit:cover}
.ab-photo figcaption{margin-top:16px;color:var(--muted);font-size:.86rem;line-height:1.55;font-style:italic;max-width:40ch}

/* story sections */
.ab-cols{display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr);gap:clamp(32px,6vw,96px);align-items:start}
.ab-cols--flip{grid-template-columns:minmax(0,.95fr) minmax(0,1.05fr);align-items:center}
.ab-kick small,.ab-eyebrow{display:block;margin-bottom:14px;font:600 .78rem var(--f-mono);letter-spacing:.14em;text-transform:uppercase;color:#8fd8ff}
.ab-kick .h2{max-width:18ch}
.ab-prose p{color:var(--ink-2);font-size:1.06rem;line-height:1.8;margin:0 0 18px;max-width:62ch}
.ab-story{padding-top:clamp(40px,6vw,80px)}
.ab-turn{background:linear-gradient(180deg,transparent,rgba(12,19,40,.55) 30%,rgba(12,19,40,.55) 70%,transparent)}

/* the invoice: the shape of the problem, deliberately without numbers */
.ab-inv{padding:26px 26px 22px;border-radius:24px;max-width:440px}
.ab-inv-h{display:flex;justify-content:space-between;align-items:baseline;margin-bottom:22px;padding-bottom:14px;border-bottom:1px dashed rgba(255,255,255,.14)}
.ab-inv-h span{font:700 1.02rem var(--f-display);color:var(--ink)}
.ab-inv-h i{font:500 .78rem var(--f-mono);font-style:normal;color:var(--muted);letter-spacing:.12em;text-transform:uppercase}
.ab-bars{display:grid;grid-template-columns:1fr 1fr;gap:18px;align-items:end;height:220px}
.ab-bar{display:flex;flex-direction:column;justify-content:flex-end;height:100%;gap:12px}
.ab-bar b{display:block;height:calc(var(--h) * 160px);border-radius:14px 14px 6px 6px;background:linear-gradient(180deg,rgba(62,220,242,.55),rgba(20,99,255,.35));border:1px solid rgba(140,200,255,.3);transform-origin:bottom}
.ab-bar--up b{background:linear-gradient(180deg,rgba(255,95,215,.7),rgba(123,58,245,.45));border-color:rgba(255,140,230,.45);box-shadow:0 18px 50px -18px rgba(224,75,214,.7)}
.ab-bar span{font-size:.84rem;color:var(--ink-2);line-height:1.35}
.ab-inv-f{margin:20px 0 0;color:var(--muted);font-size:.86rem;line-height:1.55}
/* bars are drawn at rest; with JS and motion allowed they grow when the invoice comes into view */
.ab-inv.ab-anim .ab-bar b{transform:scaleY(.04);transition:transform 1.1s cubic-bezier(.16,1,.3,1)}
.ab-inv.ab-anim .ab-bar--up b{transition-delay:.35s}
.ab-inv.ab-anim.go .ab-bar b{transform:none}

/* the promise: the page's one statement */
.ab-vow{position:relative;text-align:center;padding:clamp(48px,7vw,88px) clamp(24px,5vw,72px);border-radius:32px;overflow:hidden;isolation:isolate;
  background:linear-gradient(180deg,rgba(255,255,255,.05),rgba(255,255,255,.015)),rgba(10,16,36,.7);border:1px solid rgba(160,180,255,.18)}
.ab-vow::before{content:"";position:absolute;inset:-40% -10% auto;height:120%;z-index:-1;background:radial-gradient(50% 50% at 50% 50%,rgba(123,58,245,.28),transparent 70%)}
.ab-vow small{display:block;margin-bottom:16px;font:600 .78rem var(--f-mono);letter-spacing:.14em;text-transform:uppercase;color:#8fd8ff}
.ab-vow h2{margin:0 auto 14px;font-size:clamp(2.2rem,5vw,3.8rem);letter-spacing:-.035em;line-height:1.05;font-weight:800;max-width:16ch}
.ab-vow-l{margin:0 auto 22px;font:600 clamp(1.1rem,1.6vw,1.35rem) var(--f-display);color:#fff;max-width:40ch}
.ab-vow-p{margin:0 auto 30px;color:var(--ink-2);line-height:1.75;max-width:64ch}

/* products: real "from" prices */
.ab-prods{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:14px}
.ab-prod{display:flex;flex-direction:column;gap:12px;padding:22px 20px;border-radius:20px;text-decoration:none;color:inherit}
.ab-prod h3{margin:0;font-size:1.08rem}
.ab-prod p{margin:0;color:var(--ink-2);font-size:.9rem;line-height:1.6;flex:1}
.ab-prod .fr{font:500 .82rem var(--f-mono);color:var(--muted)}
.ab-prod .fr b{color:#fff;font-weight:700}
.ab-prod .go{display:inline-flex;align-items:center;gap:6px;color:#9CC9FF;font-weight:600;font-size:.88rem}
.ab-prod:hover .go{color:#fff}
.ab-ic{display:inline-flex;width:40px;height:40px;align-items:center;justify-content:center;border-radius:12px;background:rgba(123,92,255,.12);border:1px solid rgba(170,150,255,.22)}

/* team */
.ab-roles{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}
.ab-role{padding:26px 24px;border-radius:22px}
.ab-role h3{margin:18px 0 10px;font-size:1.12rem;line-height:1.3}
.ab-role p{margin:0;color:var(--ink-2);line-height:1.7;font-size:.95rem}
.ab-where{display:flex;gap:14px;align-items:flex-start;margin:34px 0 0;padding:20px 22px;border-radius:18px;border:1px solid var(--line);color:var(--ink-2);line-height:1.7;max-width:880px}
.ab-where span{flex:none;margin-top:2px}

/* closing CTA (the design's inner-page final section) */
.wh-final{padding:clamp(100px,12vw,160px) 0;text-align:center;background:radial-gradient(50% 70% at 50% 50%,rgba(123,58,245,.2),transparent 70%)}
.wh-final h2{font-size:clamp(2.1rem,4.4vw,3.4rem);font-weight:800;letter-spacing:-.03em;margin:0 0 12px}
.wh-final p{color:var(--ink-2);font-size:1.1rem;margin:0 auto 28px;max-width:60ch}
.wh-final .final-ctas{display:flex;gap:12px;flex-wrap:wrap;justify-content:center}
.ab-final-lead{font-style:italic;color:var(--muted)!important;font-size:1rem!important;max-width:66ch!important;margin-bottom:26px!important}

@media (max-width:1180px){.ab-prods{grid-template-columns:repeat(3,minmax(0,1fr))}}
@media (max-width:900px){.ab-hero-in,.ab-cols,.ab-cols--flip{grid-template-columns:1fr}.ab-photo{justify-self:start}.ab-roles{grid-template-columns:1fr}.ab-prods{grid-template-columns:1fr 1fr}.ab-cols--flip .ab-invoice{order:2}}
@media (max-width:560px){.ab-prods{grid-template-columns:1fr}.ab-bars{height:180px}.ab-bar b{height:calc(var(--h) * 120px)}}
