// full-page if no selector; else screenshot each selector's element.
const { chromium } = require('/root/nxeon-worktrees/marketing-nxm/node_modules/playwright');
(async () => {
  const [out, url, w, ...sels] = process.argv.slice(2);
  const browser = await chromium.launch({ args: ['--disable-gpu'] });
  try {
    const ctx = await browser.newContext({ viewport: { width: +w, height: +w < 600 ? 844 : 900 }, deviceScaleFactor: 1 });
    const page = await ctx.newPage();
    await page.routeWebSocket(/webpack-hmr/, () => {});
    const errs = [];
    page.on('pageerror', e => errs.push('pageerror: ' + e.message));
    page.on('console', m => { if (m.type() === 'error') errs.push('console: ' + m.text().slice(0, 300)); });
    await page.goto(url, { waitUntil: 'networkidle', timeout: 90000 });
    await page.waitForTimeout(1500);
    // trigger reveal-on-scroll
    await page.evaluate(async () => { for (let y = 0; y < document.body.scrollHeight; y += 500) { window.scrollTo(0, y); await new Promise(r => setTimeout(r, 60)); } window.scrollTo(0, 0); });
    await page.waitForTimeout(800);
    if (!sels.length) {
      await page.screenshot({ path: `${out}.png`, fullPage: true });
    } else {
      let i = 0;
      for (const s of sels) {
        const el = await page.$(s);
        if (!el) { errs.push('missing selector ' + s); continue; }
        await el.scrollIntoViewIfNeeded();
        await page.waitForTimeout(400);
        await el.screenshot({ path: `${out}-${i++}.png` });
      }
    }
    const ov = await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth);
    console.log('horizontal overflow px:', ov);
    console.log(errs.join('\n') || 'no errors');
  } finally { await browser.close(); }
})();

