/* ============ developers: the example request runs once when it comes into view ============ */
(function request() {
  const term = $('#dv-term'); if (!term || RM) return;
  const cmd = $('.dv-cmd', term), full = cmd.innerHTML;
  term.classList.add('dv-wait');
  const io = watch(term, async v => {
    if (!v) return; io.disconnect();
    const text = cmd.textContent; cmd.textContent = '';
    for (let i = 1; i <= text.length; i += 2) { cmd.textContent = text.slice(0, i); await wait(14); }
    cmd.innerHTML = full; await wait(450);
    term.classList.remove('dv-wait');
  }, { threshold: 0.45 });
})();
EOF
