.ft-hero-in{text-align:center;display:flex;flex-direction:column;align-items:center}
.ft-hero h1{max-width:18ch;font-size:clamp(2.5rem,5.2vw,4.4rem)}
.ft-hero .k-lede{margin-inline:auto}
.ft-hero .gh-ctas,.ft-hero .k-jump{justify-content:center}
/* the flagship: copy + Claude session on the Matrix wallpaper */
.ft-claude{padding-top:clamp(24px,4vw,48px)}
.ft-flag{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.05fr);gap:clamp(28px,5vw,64px);align-items:center;padding:clamp(22px,4vw,48px);border-radius:32px;overflow:hidden}
.ft-flag::before{content:"";position:absolute;inset:0;border-radius:inherit;pointer-events:none;background:radial-gradient(50% 70% at 85% 20%,rgba(138,112,251,.18),transparent 70%),radial-gradient(40% 60% at 10% 90%,rgba(59,130,246,.14),transparent 70%)}
.ft-flag>*{position:relative}
.ft-badge{display:inline-flex;align-items:center;gap:8px;margin:0 0 18px;padding:6px 13px;border-radius:999px;border:1px solid rgba(217,119,87,.35);background:rgba(217,119,87,.1);color:#F2C2AE;font:600 .8rem var(--f-body)}
.ft-badge img{width:16px;height:16px}
.ft-flag-cta{margin-top:30px}
.ft-you{margin:0 0 12px auto;max-width:86%;padding:10px 13px;border-radius:14px 14px 4px 14px;border:1px solid rgba(155,120,255,.3);background:rgba(123,92,255,.12);color:#EEF0FA;line-height:1.5}
.ft-ai{max-width:94%;padding:12px 13px;border-radius:14px 14px 14px 4px;border:1px solid rgba(255,255,255,.08);background:rgba(255,255,255,.03);color:#C9CCD8}
.ft-ai>p:first-child{margin:0 0 10px}
.ft-steps{list-style:none;margin:0;padding:0;display:grid;gap:7px;font:12.5px/1.5 var(--f-mono);color:#9AA0B4}
.ft-steps li{display:flex;gap:9px;align-items:flex-start;transition:opacity .35s ease,color .35s ease}
.ft-steps li::before{content:"✓";flex:none;display:grid;place-items:center;width:16px;height:16px;margin-top:1px;border-radius:50%;background:rgba(63,216,154,.15);color:#3FD89A;font-size:10px;transition:background-color .3s,color .3s}
.ft-done{margin:12px 0 0;display:inline-flex;align-items:center;gap:8px;padding:6px 10px;border-radius:9px;border:1px solid rgba(63,216,154,.3);background:rgba(63,216,154,.1);color:#7FF0C0;font:600 .8rem var(--f-mono);transition:opacity .4s ease}
/* with motion allowed, the steps tick through once when the session comes into view */
.ft-chat.ft-run .ft-steps li{opacity:.35}
.ft-chat.ft-run .ft-steps li::before{content:"";background:rgba(255,255,255,.06)}
.ft-chat.ft-run .ft-steps li.ok{opacity:1;color:#C9CCD8}
.ft-chat.ft-run .ft-steps li.ok::before{content:"✓";background:rgba(63,216,154,.15)}
.ft-chat.ft-run .ft-done{opacity:0}
.ft-chat.ft-run.go .ft-done{opacity:1}
.ft-more{display:inline-flex;margin-left:4px;color:#9CC9FF;font-weight:600;text-decoration:none}
.ft-more::after{content:"→";margin-left:5px}
.ft-more:hover{color:#fff}
.ft-layers{margin-top:8px}
/* specs */
.ft-spec-h{align-items:flex-end}
.ft-spec{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));margin:0;border-radius:24px;overflow:hidden}
.ft-spec div{padding:24px 26px;border-right:1px solid var(--line);border-bottom:1px solid var(--line)}
.ft-spec div:nth-child(3n){border-right:0}
.ft-spec div:nth-last-child(-n+3){border-bottom:0}
.ft-spec dt{margin-bottom:8px;font:600 .74rem var(--f-mono);letter-spacing:.14em;text-transform:uppercase;color:#8fd8ff}
.ft-spec dd{margin:0;font:600 1.02rem var(--f-display);color:var(--ink);line-height:1.45}
@media (max-width:980px){.ft-flag{grid-template-columns:1fr}}
@media (max-width:760px){.ft-spec{grid-template-columns:1fr 1fr}.ft-spec div{border-right:1px solid var(--line)!important;border-bottom:1px solid var(--line)!important}.ft-spec div:nth-child(2n){border-right:0!important}.ft-spec div:nth-last-child(-n+2){border-bottom:0!important}}
