import "server-only";
import { liveRegions, type NxmLoad } from "./lib";

/** /features — the live page's copy; the one system fact on it, where servers
 *  run, comes from the regions that actually have an enabled node. */
const AREA: Record<string, string> = {
  sgp1: "APAC",
  fsn1: "Europe", nbg1: "Europe", hel1: "Europe", gra1: "Europe", rbx1: "Europe", waw1: "Europe",
  bhs1: "North America", ash1: "North America", hil1: "North America",
};

export async function regionSpec(): Promise<string> {
  const regions = await liveRegions();
  if (!regions.length) throw new Error("nxm /features: no enabled regions");
  const names = [...new Set(regions.map((r) => r.label))];
  const areas = [...new Set(regions.map((r) => AREA[r.code]).filter(Boolean))];
  const list = (xs: string[], joiner: string) => (xs.length < 2 ? xs.join("") : `${xs.slice(0, -1).join(", ")} ${joiner} ${xs[xs.length - 1]}`);
  return `${list(names, "or")}${areas.length ? `, low latency across ${list(areas, "and")}` : ""}`;
}

export async function load(_p: Record<string, string>): Promise<NxmLoad> {
  return { slots: { location: await regionSpec() } };
}

