import { db } from "@/lib/db";
import { getSetting } from "@/lib/settings";

/**
 * Google / Trustpilot / HostAdvice badges — REAL DATA ONLY.
 *
 * Same aggregation as the live site's components/marketing/ReviewBadges.tsx
 * (approved reviews per external source, linked to the owner's real profile),
 * but with no placeholder fallback: that component shows hardcoded scores
 * (4.9/312 etc.) when no real reviews exist, which is the case today. Owner's
 * rule for the new site: badges appear only when there is something real
 * behind them. Returns null otherwise.
 */
const SOURCES = [
  { key: "TRUSTPILOT", name: "Trustpilot", star: "#00b67a", url: "review_url_trustpilot" },
  { key: "HOSTADVICE", name: "HostAdvice", star: "#f5a623", url: "review_url_hostadvice" },
  { key: "GOOGLE", name: "Google", star: "#fbbc05", url: "review_url_google" },
] as const;

export async function realReviewBadges() {
  try {
    const grouped = await db.review.groupBy({
      by: ["source"],
      where: { approved: true, source: { in: SOURCES.map((s) => s.key) } },
      _avg: { rating: true },
      _count: { _all: true },
    });
    const out: { name: string; star: string; score: string; count: number; href: string }[] = [];
    for (const s of SOURCES) {
      const g = grouped.find((x) => x.source === s.key);
      const href = (await getSetting(s.url)).trim();
      if (!g || g._count._all < 1 || !href) continue;
      out.push({ name: s.name, star: s.star, score: (g._avg.rating ?? 0).toFixed(1), count: g._count._all, href });
    }
    return out;
  } catch {
    return [];
  }
}

