import "server-only";
import { db } from "@/lib/db";
import { PROMPTS } from "@/lib/ai-build";
import { AU_ICONS } from "../_aurora/icons";
import { esc, introSpan, usd, vpsPlans, type NxmLoad } from "./lib";

/**
 * /vibe-coding — the live page's content (app/(marketing)/vibe-coding +
 * components/marketing/aihostingtemplate/VibeCodingLanding). System data:
 *  - the pricing teaser: three REAL VPS plans (first, a middle pick, last —
 *    the live page's own selection), intro price only when the plan has one,
 *    each with its real deploy link;
 *  - the prompt-library count: the catalogue the dashboard's Claude Code hub
 *    renders (lib/ai-build PROMPTS);
 *  - testimonials: only ones the admin has published. The live page falls back
 *    to illustrative use-cases when there are none; the new site shows nothing
 *    instead (owner rule: no invented reviews).
 */
const ROCKET = `<span class="nxm-rk"><svg class="au-ic" viewBox="0 0 24 24" aria-hidden="true">${AU_ICONS.rocket}</svg></span>`;
const ARW = `<span class="nxm-arw" aria-hidden="true">→</span>`;
const d = (dollars: number) => usd(Math.round(dollars * 100));

export async function load(_p: Record<string, string>): Promise<NxmLoad> {
  const [all, testimonials] = await Promise.all([
    vpsPlans(),
    db.testimonial.findMany({ where: { published: true }, orderBy: { sortOrder: "asc" } }),
  ]);
  if (!all.length) throw new Error("nxm /vibe-coding: no active VPS plans");
  if (!PROMPTS.length) throw new Error("nxm /vibe-coding: empty prompt catalogue");

  const picks = all.length <= 3 ? all : [all[0], all[Math.floor((all.length - 1) / 2)], all[all.length - 1]];
  const popular = picks[Math.floor((picks.length - 1) / 2)];
  const plans = `<div class="vb-plans">${picks
    .map((p) => {
      const pop = p === popular;
      const price = p.i != null
        ? `<p class="pp"><b>${d(p.i)}</b><s>${d(p.p)}</s><span>${introSpan(p.it)}</span></p><p class="then">Then ${d(p.p)} a month</p>`
        : `<p class="pp"><b>${d(p.p)}</b><span>/month</span></p><p class="then"></p>`;
      const cta = pop
