import "server-only";
import { getSettingInt, SETTINGS_DEFAULTS } from "@/lib/settings";
import { APP_URL } from "@/components/marketing/StructuredData";
import { usd, type NxmLoad } from "./lib";

/**
 * /block-storage — the live page's content, every price from the system.
 *
 * The rate is `volume_price_cents_per_gb`: the admin "Block storage price"
 * setting that lib/actions-volumes.ts orderVolume() charges and the dashboard's
 * volumes page quotes. (lib/disk-expand.ts extraDiskPerGbCents() is a different
 * knob — it prices growing a server's OWN root disk — and the two can be set
 * independently, so it can't stand in for the volume price.) The live page
 * hardcodes $0.10; this reads the value at request time.
 */
export async function volumePerGbCents(): Promise<number> {
  const cents = await getSettingInt("volume_price_cents_per_gb", Number(SETTINGS_DEFAULTS.volume_price_cents_per_gb));
  if (!Number.isFinite(cents) || cents <= 0) throw new Error("nxm /block-storage: no block-storage price configured");
  return Math.round(cents);
}

export async function meta(_p: Record<string, string>) {
  const per = usd(await volumePerGbCents());
  return {
    description: `Add-on NVMe block-storage volumes at ${per} per GB / month. Attach to any VPS, keep your data on detach, and add capacity without resizing your server.`,
  };
}

export async function load(_p: Record<string, string>): Promise<NxmLoad> {
  const per = await volumePerGbCents();
  const at = (gb: number) => usd(gb * per);
  const price = (per / 100).toFixed(2);
  return {
    slots: { price: usd(per), v50: at(50), v100: at(100), v500: at(500), v650: at(650) },
    jsonLd: [{
      "@context": "https://schema.org", "@type": "Product", name: "Nxeon Block Storage",
      description: "Add-on NVMe block-storage volumes you attach to any Nxeon VPS, billed per GB per month.",
      brand: { "@type": "Brand", name: "Nxeon" },
      offers: {
        "@type": "Offer", priceCurrency: "USD", price, availability: "https://schema.org/InStock", url: APP_URL + "/block-storage",
        priceSpecification: { "@type": "UnitPriceSpecification", price, priceCurrency: "USD", referenceQuantity: { "@type": "QuantitativeValue", value: 1, unitCode: "E34", unitText: "GB per month" } },
      },
    }],
  };
}

