import "server-only";
import {
  getHealth, overallStatus, uptimeSummary, allTimelines, listIncidents, UPTIME_WINDOW_MS,
  type CompStatus, type TimelineBucket, type IncidentView,
} from "@/lib/monitoring";
import { OVERALL_TITLE, COMPONENT_LABELS, COMPONENT_DESCRIPTIONS, SEVERITY_LABEL, type HealthComponentKey } from "@/lib/status-copy";
import { esc, type NxmLoad } from "./lib";

/**
 * /status — the live status page (app/status/page.tsx), same readers, same
 * public-safe wording (lib/status-copy): the four probes' state right now,
 * uptime and a bucketed history per component from real HealthSample rows
 * (a component with no samples says "No history yet", never an assumed 100%),
 * and open + recently resolved incidents (curated title/body only — never a
 * probe's internal `detail`).
 *
 * Everything that changes lives in one `#st-live` region; the page script
 * re-fetches this same page every ~15s and swaps that region, so the server
 * stays the only reader of health (no public JSON surface) — the same design
 * as the live page's router.refresh().
 */
const ORDER: HealthComponentKey[] = ["web", "proxmox", "worker", "db"]; // the live page's order
const WINDOW_DAYS = Math.round(UPTIME_WINDOW_MS / (24 * 60 * 60_000));
const WORD: Record<CompStatus, string> = { operational: "Operational", degraded: "Degraded performance", down: "Outage" };
const SHORT: Record<CompStatus, string> = { operational: "Operational", degraded: "Degraded", down: "Outage" };
const TONE: Record<CompStatus, string> = { operational: "ok", degraded: "warn", down: "bad" };
const KEY: Record<CompStatus, string> = { operational: "#3FD89A", degraded: "#F2B64B", down: "#FF6A8A" };
const SEV_TONE: Record<IncidentView["severity"], string> = { down: "bad", degraded: "warn", maintenance: "info" };

const fmt = (d: string | number | Date) =>
  new Date(d).toLocaleString("en-US", { dateStyle: "medium", timeStyle: "short", timeZone: "UTC" });
const day = (ms: number) => new Date(ms).toLocaleDateString("en-US", { month: "short", day: "numeric", timeZone: "UTC" });

/** Uptime % → words; honest when there's no history yet. */
function uptimeLabel(pct: number | null) {
  if (pct === null) return "No history yet";
  return pct >= 99 ? `${pct.toFixed(2)}% uptime` : `${pct.toFixed(1)}% uptime`;
}

function strip(buckets: TimelineBucket[]) {
  if (!buckets.length) return `<p class="st-none">No history yet</p>`;
  return `<div class="st-strip" role="img" aria-label="Status history, one bar per day for the last ${WINDOW_DAYS} days">${buckets
    .map((b) => {
      const has = b.status !== null && b.total > 0;
      return `<span class="${has ? TONE[b.status as CompStatus] : "nd"}" title="${esc(`${day(b.start)}: ${has ? SHORT[b.status as CompStatus] : "no data"}`)}"></span>`;
    })
    .join("")}</div>`;
}

function incidentCard(i: IncidentView) {
  const resolved = !!i.resolvedAt;
  const comp = i.component ? COMPONENT_LABELS[i.component] : "Platform-wide";
  return `<article class="st-inc"><div class="st-inc-h"><span class="st-sev ${SEV_TONE[i.severity] ?? "warn"}${resolved ? " past" : ""}" aria-hidden="true"></span><h3>${esc(i.title)}</h3><span class="k-chip${resolved ? " on" : " act"}">${resolved ? "Resolved" : "Active"}</span></div><p>${esc(i.body)}</p><small><span class="st-sevw ${SEV_TONE[i.severity] ?? "warn"}">${esc(SEVERITY_LABEL[i.severity] ?? i.severity)}</span> · ${esc(comp)} · Started ${esc(fmt(i.startedAt))} UTC${resolved && i.resolvedAt ? ` · Resolved ${esc(fmt(i.resolvedAt))} UTC` : ""}</small></article>`;
}

export async function load(_p: Record<string, string>): Promise<NxmLoad> {
  const [health, uptime, timelines, incidents] = await Promise.all([
    getHealth(), uptimeSummary(), allTimelines(UPTIME_WINDOW_MS, WINDOW_DAYS), listIncidents(),
  ]);
  const overall = overallStatus(health);

  const banner = `<div class="status-card st-card" style="--k:${KEY[overall]}"><div class="status-main"><span class="dot ${overall === "operational" ? "live" : TONE[overall]}" aria-hidden="true"></span><div><h1 id="st-title">${esc(OVERALL_TITLE[overall])}</h1><small>Last checked ${esc(fmt(health.checkedAt))} UTC</small></div></div><ul class="status-list">${ORDER.map((k) => {
    const s = health[k].status;
    return `<li><span class="dot${s === "operational" ? "" : " " + TONE[s]}" aria-hidden="true"></span>${esc(COMPONENT_LABELS[k])}<span class="visually-hidden">: ${WORD[s]}</span></li>`;
  }).join("")}</ul></div>`;

  const comps = `<section class="st-block" aria-labelledby="st-c"><div class="st-bh"><h2 id="st-c">Components</h2><span>Uptime over the last ${WINDOW_DAYS} days</span></div><div class="st-comps au-glass">${ORDER.map((k) => {
    const s = health[k].status;
    return `<div class="st-comp"><div class="st-ch"><div><h3>${esc(COMPONENT_LABELS[k])}</h3><p>${esc(COMPONENT_DESCRIPTIONS[k])}</p></div><span class="st-state ${TONE[s]}"><i aria-hidden="true"></i>${WORD[s]}</span></div>${strip(timelines[k])}<div class="st-axis"><span>${WINDOW_DAYS} days ago</span><b>${esc(uptimeLabel(uptime[k].pct))}</b><span>Today</span></div></div>`;
  }).join("")}</div></section>`;

  const inc = incidents.open.length || incidents.resolved.length
    ? `${incidents.open.length ? `<div class="st-incs au-glass"><p class="st-il">Active incidents</p>${incidents.open.map(incidentCard).join("")}</div>` : ""}${incidents.resolved.length ? `<div class="st-incs au-glass"><p class="st-il">Past incidents</p>${incidents.resolved.map(incidentCard).join("")}</div>` : ""}`
    : `<div class="st-incs au-glass st-empty"><p>No incidents reported in this window. When a component stays unhealthy across monitoring checks, or an operator posts one, it will appear here with a full timeline.</p></div>`;
  const incSec = `<section class="st-block" aria-labelledby="st-i"><div class="st-bh"><h2 id="st-i">Incident history</h2></div>${inc}</section>`;

  return { slots: { "live:html": banner + comps + incSec } };
}

