/* ============ status: refresh the live region every ~15s, like the live page ============ */
/* Re-fetches THIS page (the server stays the only reader of health, no public
   JSON) and swaps #st-live. Pauses while the tab is hidden; refreshes at once
   when it becomes visible again. */
(function refresh() {
  const live = $('#st-live'), ref = $('#st-ref'); if (!live) return;
  let timer = 0, busy = false;
  const tick = async () => {
    if (busy || document.visibilityState !== 'visible') return;
    busy = true; ref && ref.classList.add('on');
    try {
      const r = await fetch(location.pathname + location.search, { cache: 'no-store', headers: { accept: 'text/html' } });
      if (r.ok) {
        const next = new DOMParser().parseFromString(await r.text(), 'text/html').getElementById('st-live');
        if (next && next.innerHTML !== live.innerHTML) live.innerHTML = next.innerHTML;
      }
    } catch (e) { /* keep the last good state */ }
    busy = false; setTimeout(() => ref && ref.classList.remove('on'), 700);
  };
  const start = () => { if (!timer) timer = setInterval(tick, 15000); };
  const stop = () => { clearInterval(timer); timer = 0; };
  document.addEventListener('visibilitychange', () => { if (document.visibilityState === 'visible') { tick(); start(); } else stop(); });
  start();
})();
EOF
