import "server-only";
import type { BlogPost } from "@prisma/client";
import { getHelpData, categorySlug } from "@/lib/help";
import { readMinutes } from "@/lib/blog";
import { APP_URL } from "@/components/marketing/StructuredData";
import { esc, nxmHref, type NxmLoad } from "./lib";

/**
 * /help — the live help centre (app/help/page.tsx + lib/help.ts): every
 * published guide, grouped by category, with the same `?q=` search and `?c=`
 * topic filter. Articles open on the new blog (/blog/[slug]).
 * Category marks are the design's icons instead of the live page's emoji.
 */
const ICON: Record<string, string> = {
  gaming: "game", vps: "server", tutorials: "terminal", security: "shield", "control-panels": "gear",
  domains: "globe", hosting: "cloud", guides: "check", comparisons: "chart",
};
const icon = (slug: string) => ICON[slug] ?? "search";

function matches(post: BlogPost, q: string) {
  return `${post.title} ${post.excerpt} ${post.category} ${(post.tags ?? []).join(" ")}`.toLowerCase().includes(q);
}

const help = nxmHref("/help");
const article = (p: BlogPost) =>
  `<a class="au-card hc-art" href="${esc(nxmHref(`/blog/${encodeURIComponent(p.slug)}`))}"><span class="hc-ai" data-au-icon="${icon(categorySlug(p.category || "Guides"))}" data-grad></span><span class="hc-at"><b>${esc(p.title)}</b><span>${esc(p.excerpt ?? "")}</span><small>${readMinutes(p.body)} min read</small></span></a>`;

export async function meta(p: Record<string, string>) {
  const filtered = Boolean((p.q ?? "").trim() || (p.c ?? "").trim());
  // search results and topic filters are thin variants of /help
  return { canonical: "/help", noindex: filtered };
}

export async function load(p: Record<string, string>): Promise<NxmLoad> {
  const rawQ = (p.q ?? "").trim();
  const query = rawQ.toLowerCase();
  const activeCat = (p.c ?? "").trim().toLowerCase();
  const { sections, popular, total } = await getHelpData();

  const filtered = sections
    .filter((s) => (activeCat ? categorySlug(s.category.name) === activeCat : true))
    .map((s) => ({ ...s, posts: query ? s.posts.filter((x) => matches(x, query)) : s.posts }))
    .filter((s) => s.posts.length > 0);
  const isFiltering = Boolean(query || activeCat);
  const resultCount = filtered.reduce((n, s) => n + s.posts.length, 0);

  let out = "";
  if (!query) {
    out += `<section class="hc-block" aria-labelledby="hc-topics"><div class="hc-bh"><h2 id="hc-topics">Browse by topic</h2>${activeCat ? `<a href="${help}">← All topics</a>` : ""}</div><div class="hc-topics">${sections
      .map((s) => {
        const slug = categorySlug(s.category.name);
        const on = slug === activeCat;
        return `<a class="au-card hc-topic${on ? " on" : ""}" href="${on ? help : `${help}?c=${encodeURIComponent(slug)}`}"${on ? ' aria-current="true"' : ""}><span class="k-ic" data-au-icon="${icon(slug)}" data-grad></span><span><b>${esc(s.category.name)}<i>${s.posts.length}</i></b><small>${esc(s.category.blurb)}</small></span></a>`;
      })
      .join("")}</div></section>`;
  }
  if (!isFiltering && popular.length) {
    out += `<section class="hc-block" aria-labelledby="hc-pop"><div class="hc-bh"><h2 id="hc-pop">Popular articles</h2></div><div class="hc-arts">${popular.map(article).join("")}</div></section>`;
  }
  if (isFiltering) {
    out += `<div class="hc-res"><p>${resultCount === 0 ? "No results" : `${resultCount} article${resultCount === 1 ? "" : "s"}`}${query ? ` for <b>“${esc(rawQ)}”</b>` : ""}</p><a href="${help}">Clear</a></div>`;
  }
  if (!filtered.length) {
    out += `<div class="hc-empty au-glass"><span class="k-ic" data-au-icon="search" data-grad></span><h2>Nothing found</h2><p>Try a different search term or browse the topics above. Still stuck? Our team is one ticket away.</p><div class="gh-ctas"><a class="nxm-glassbtn" href="${help}"><span class="nxm-bt">Browse all topics</span></a><a class="nxm-btn" href="${esc(nxmHref("/contact"))}"><span class="nxm-bt">Contact support</span><span class="nxm-arw" aria-hidden="true">→</span></a></div></div>`;
  } else {
    out += filtered
      .map((s) => {
        const slug = categorySlug(s.category.name);
        return `<section class="hc-block hc-cat" id="${esc(slug)}" aria-labelledby="hc-c-${esc(slug)}"><div class="hc-ch"><span class="k-ic" data-au-icon="${icon(slug)}" data-grad></span><div><h2 id="hc-c-${esc(slug)}">${esc(s.category.name)}</h2><p>${esc(s.category.blurb)}</p></div></div><div class="hc-arts">${s.posts.map(article).join("")}</div></section>`;
      })
      .join("");
  }

  const jsonLd = isFiltering || !popular.length ? [] : [{
    "@context": "https://schema.org", "@type": "ItemList", name: "Popular help articles",
    itemListElement: popular.map((x, i) => ({ "@type": "ListItem", position: i + 1, url: `${APP_URL}/blog/${x.slug}`, name: x.title })),
  }];

  return { slots: { total: String(total), q: rawQ, "results:html": out }, jsonLd };
}

