import type { Metadata } from "next";
import { NxmPage } from "./_components/NxmPage";
import * as C from "./_pages/not-found/content";
import "./_pages/not-found/page.css";

/**
 * The new site's 404 — shown whenever a page under /nxm calls notFound()
 * (unknown mod, post, game family…). A native page in the design language
 * (tools/nxm/native/not-found, generated by tools/nxm/port_notfound.py):
 * the site nav, a real search (the help center's), and links to real pages.
 * Outside staging the /nxm layout itself 404s, which bubbles past this
 * boundary to the root not-found — so production never sees it.
 */
export const metadata: Metadata = {
  title: "Page not found",
  robots: { index: false, follow: false },
};

export default function NotFound() {
  return <NxmPage slug="not-found" route="/404" body={C.BODY_HTML} attrs={C.BODY_ATTRS} />;
}
