<div class="container dc-lay">
  <aside class="dc-toc" aria-label="On this page"><div class="dc-toc-in"><b>On this page</b><ol><li><a href="#base-url">Base URL</a></li><li><a href="#authentication">Authentication</a></li><li><a href="#list-servers">GET /api/v1/servers</a></li><li><a href="#roadmap">On the roadmap</a></li></ol></div></aside>
