      <span class="k">"status"</span>: <span class="ok">"RUNNING"</span>,
      <span class="k">"plan"</span>: <span class="s">"standard"</span>,
      <span class="k">"ipAddress"</span>: <span class="s">"51.79.226.200"</span>,
      <span class="k">"createdAt"</span>: <span class="s">"2026-07-24T09:41:00Z"</span>
    }
  ]
}</code></pre>
    </section>

    <section class="dc-sec" id="roadmap" aria-labelledby="dc-s4">
